// Uploads the built artifact to the release bucket.
const fs = require("fs");

const BUCKET = ""; // TODO: release bucket name, not recorded in this repo
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

// Puts the given object into the release bucket. In this environment the
// bucket is a local directory rooted at the bucket's base path.
function putObject(bucket, name, body) {
  const base = process.env.BUCKET_BASE || ".bucket";
  const dir = `${base}/${bucket}`;
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(`${dir}/${name}`, body);
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  putObject(BUCKET, name, body);
  console.log(`uploaded ${name} (${body.length} bytes)`);
}

main();

